<script setup>
import { computed, ref } from 'vue';
import { offerPresentation } from '../../../domain/marketing.js';
import { voucherPayload } from '../../../domain/studentPrograms.js';
import Icon from '../../ui/EditionIcon.vue';
import Modal from '../../ui/EditionModal.vue';

const props=defineProps({offers:{type:Array,default:()=>[]},vouchers:{type:Array,default:()=>[]},products:{type:Array,default:()=>[]},currency:{type:String,default:'RM'},canManage:Boolean,busy:Boolean,error:{type:String,default:''}});
const emit=defineEmits(['new-campaign','save-voucher']);
const voucher=ref(null),localError=ref('');
const voucherOffers=computed(()=>props.offers.filter(row=>row.redemptionMode==='voucher'));
const presentation=row=>{const product=props.products.find(item=>item.id===row.rewardProductId),variant=product?.variants?.find(item=>item.id===row.rewardVariantId);return offerPresentation({...row,rewardProductName:product?`${product.name}${variant?` · ${variant.name}`:''}`:''},props.currency);};
const date=value=>value?new Intl.DateTimeFormat('en-MY',{dateStyle:'medium',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(value)):'No expiry';
const localTime=value=>{const parsed=new Date(value||Date.now());const offset=parsed.getTimezoneOffset()*60000;return new Date(parsed-offset).toISOString().slice(0,16);};
const voucherState=row=>{const now=Date.now(),from=new Date(row.validFrom).getTime(),until=row.validUntil?new Date(row.validUntil).getTime():Infinity,exhausted=row.maxRedemptions!=null&&Number(row.redeemedCount)>=Number(row.maxRedemptions);if(!row.enabled)return {label:'Inactive',tone:'warning'};if(exhausted)return {label:'Used up',tone:'warning'};if(from>now)return {label:'Scheduled',tone:''};if(until<=now)return {label:'Expired',tone:'warning'};return {label:'Ready',tone:'ready'};};
function openVoucher(row=null){voucher.value=row?{id:row.id,promotionId:row.promotionId,codeHint:row.codeHint,expectedVersion:Number(row.version),enabled:!!row.enabled,validFrom:localTime(row.validFrom),validUntil:row.validUntil?localTime(row.validUntil):'',maxRedemptions:row.maxRedemptions??'',perCustomerLimit:row.perCustomerLimit??''}:{promotionId:voucherOffers.value[0]?.id||'',code:'',expectedVersion:0,enabled:true,validFrom:localTime(),validUntil:'',maxRedemptions:'',perCustomerLimit:'1'};localError.value='';}
function saveVoucher(){try{const creating=!voucher.value.id,payload=voucherPayload(voucher.value,{creating});emit('save-voucher',{promotionId:voucher.value.promotionId,voucherId:voucher.value.id||'',payload,done:()=>voucher.value=null});}catch(error){localError.value=error.message;}}
</script>

<template>
  <section class="mf-offers-panel">
    <div class="ed-section-head"><div><div class="ed-eyebrow">OFFERS & VOUCHERS</div><h2>Customer value, with hard limits</h2><small>Offer versions remain immutable. Campaigns link an exact version so later edits cannot rewrite historical attribution.</small></div><div v-if="canManage" class="ed-actions"><button v-if="voucherOffers.length" class="ed-btn" @click="openVoucher"><Icon name="plus"/>New voucher</button><button class="ed-btn primary" @click="emit('new-campaign')"><Icon name="spark"/>Build campaign offer</button></div></div>
    <div class="mf-offer-grid"><article v-for="row in offers" :key="`${row.id}:${row.version}`"><header><Icon :name="row.discountType==='free_item'?'bag':'percent'"/><span class="ed-pill" :class="{ready:row.enabled,warning:!row.enabled}">{{ row.enabled?'Enabled':'Draft / inactive' }}</span></header><h3>{{ row.name||row.campaignName }}</h3><strong>{{ presentation(row) }}</strong><dl><div><dt>Version</dt><dd>{{ row.version }}</dd></div><div><dt>Mode</dt><dd>{{ row.redemptionMode==='voucher'?'Voucher':'Automatic' }}</dd></div><div><dt>Window</dt><dd>{{ date(row.validFrom) }} – {{ date(row.validUntil) }}</dd></div></dl></article></div>
    <div v-if="!offers.length" class="ed-empty"><Icon name="percent"/><h3>No offer versions yet.</h3><p>Start with a campaign. MyFin will create a disabled offer first and activate the linked version only when the campaign is published.</p></div>
    <section class="ed-section"><div class="ed-section-head"><div><h3>Voucher activity</h3><small>Codes are masked after creation. Open a row to schedule, activate, pause or change its limits.</small></div><span class="ed-pill">{{ vouchers.length }} code{{ vouchers.length===1?'':'s' }}</span></div><div v-for="row in vouchers" :key="row.id" class="ed-row"><Icon name="card"/><span style="flex:1"><strong>{{ row.codeHint||row.code_hint||'Masked code' }}</strong><small>{{ row.campaignName||row.promotionName||'Promotion voucher' }} · version {{ row.version }} · {{ date(row.validFrom) }} – {{ date(row.validUntil) }}</small></span><span>{{ row.redeemedCount||row.redemptionCount||0 }}{{ row.maxRedemptions!=null?` / ${row.maxRedemptions}`:'' }} used</span><span class="ed-pill" :class="voucherState(row).tone">{{ voucherState(row).label }}</span><button v-if="canManage" class="ed-btn compact" type="button" @click="openVoucher(row)"><Icon name="edit"/>Manage</button></div><div v-if="!vouchers.length" class="ed-empty"><p>No voucher code has been created.</p></div></section>
    <Modal v-if="voucher" :title="voucher.id?'Manage voucher code':'Create voucher code'" :busy="busy" @close="voucher=null"><form id="marketing-voucher-form" class="ed-form-grid" @submit.prevent="saveVoucher"><label class="ed-field wide"><span>Voucher offer</span><select v-model="voucher.promotionId" required :disabled="!!voucher.id"><option v-for="row in voucherOffers" :key="row.id" :value="row.id">{{ row.name }} · version {{ row.version }}</option></select></label><label v-if="!voucher.id" class="ed-field wide"><span>New code</span><input v-model="voucher.code" type="password" minlength="6" maxlength="32" pattern="[A-Za-z0-9-]+" autocomplete="new-password" required><small>Shown once here; only a masked hint is returned later.</small></label><div v-else class="ed-notice wide"><Icon name="shield"/><div><strong>{{ voucher.codeHint }}</strong>The original code stays secret. Editing creates an auditable version without rotating it.</div></div><label class="ed-field"><span>Starts</span><input v-model="voucher.validFrom" type="datetime-local" required></label><label class="ed-field"><span>Ends · optional</span><input v-model="voucher.validUntil" type="datetime-local"></label><label class="ed-field"><span>Maximum uses · optional</span><input v-model="voucher.maxRedemptions" type="number" min="1" step="1"></label><label class="ed-field"><span>Per-customer limit · optional</span><input v-model="voucher.perCustomerLimit" type="number" min="1" step="1"></label><label class="mf-check wide"><input v-model="voucher.enabled" type="checkbox">Allow this code during the linked offer window</label></form><p v-if="localError||error" class="ed-notice error">{{ localError||error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="voucher=null">Cancel</button><button class="ed-btn primary" type="submit" form="marketing-voucher-form" :disabled="busy">{{ busy?'Saving…':voucher.id?'Save voucher':'Create secure voucher' }}</button></template></Modal>
  </section>
</template>

<style scoped>
.mf-offers-panel{display:grid;gap:20px}.mf-offer-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.mf-offer-grid article,.ed-section{border:1px solid var(--ed-line);background:var(--ed-paper);padding:20px}.mf-offer-grid header{display:flex;justify-content:space-between}.mf-offer-grid h3{font:400 23px var(--ed-font-sans);margin:16px 0 7px}.mf-offer-grid>article>strong{color:var(--ed-accent)}.mf-offer-grid dl{margin:18px 0 0}.mf-offer-grid dl div{display:flex;justify-content:space-between;gap:15px;border-top:1px solid var(--ed-line);padding:9px 0;font-size:10px}.mf-offer-grid dt{color:var(--ed-muted)}.ed-section h3{font:400 23px var(--ed-font-sans);margin:0}.ed-row small{display:block;margin-top:4px}.ed-btn.compact{min-height:32px;padding:0 10px}.mf-check{display:flex;align-items:center;gap:8px;font-size:11px}@media(max-width:800px){.mf-offer-grid{grid-template-columns:1fr}.ed-row{align-items:flex-start;flex-wrap:wrap}}
</style>
